// Static root. Per-run files under src/gen/ are (re)generated by the pipeline:
//   - gen/candidates.tsx  one preview Composition per generated scene variant
//   - gen/main.tsx        the single "main" Composition assembled from winners
import {Composition} from 'remotion';
import {CandidateCompositions} from './gen/candidates';
import {Main, mainMeta} from './gen/main';

export const Root = () => {
  return (
    <>
      <CandidateCompositions />
      <Composition
        id="main"
        component={Main}
        durationInFrames={mainMeta.durationInFrames}
        fps={mainMeta.fps}
        width={mainMeta.width}
        height={mainMeta.height}
      />
    </>
  );
};
